-- Targeted catalog cleanup. Keep historical names, sets, loads and session IDs.
BEGIN;
DO $$ DECLARE pair text[]; source_id text; target_id text; BEGIN
 FOREACH pair SLICE 1 IN ARRAY ARRAY[['00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000101'],['00000000-0000-4000-8000-000000000106','00000000-0000-4000-8000-000000000105']] LOOP
 source_id:=pair[1]; target_id:=pair[2];
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id=source_id) THEN
 IF NOT EXISTS (SELECT 1 FROM "Exercise" WHERE id=source_id AND "ownerUserId" IS NULL AND name IN ('Supino Reto','Agachamento')) OR NOT EXISTS (SELECT 1 FROM "Exercise" WHERE id=target_id AND "ownerUserId" IS NULL AND name IN ('Supino Reto com Barra','Agachamento Livre')) THEN RAISE EXCEPTION 'Catalog merge identity changed'; END IF;
 UPDATE "WorkoutExercise" SET "exerciseId"=target_id WHERE "exerciseId"=source_id;
 UPDATE "WorkoutExercise" SET "alternative1ExerciseId"=target_id WHERE "alternative1ExerciseId"=source_id;
 UPDATE "WorkoutExercise" SET "alternative2ExerciseId"=target_id WHERE "alternative2ExerciseId"=source_id;
 UPDATE "SessionExercise" SET "exerciseId"=target_id WHERE "exerciseId"=source_id;
 UPDATE "SessionExercise" SET "plannedExerciseId"=target_id WHERE "plannedExerciseId"=source_id;
 UPDATE "SessionExercise" SET "alternative1ExerciseId"=target_id WHERE "alternative1ExerciseId"=source_id;
 UPDATE "SessionExercise" SET "alternative2ExerciseId"=target_id WHERE "alternative2ExerciseId"=source_id;
 UPDATE "WorkoutSet" SET "exerciseId"=target_id WHERE "exerciseId"=source_id;
 UPDATE "WorkoutSetProposal" SET "targetExerciseId"=target_id WHERE "targetExerciseId"=source_id;
 -- Preserve media unless the destination already has that provider/type.
 UPDATE "ExerciseMedia" s SET "exerciseId"=target_id WHERE s."exerciseId"=source_id AND NOT EXISTS (SELECT 1 FROM "ExerciseMedia" t WHERE t."exerciseId"=target_id AND t.provider=s.provider AND t."mediaType"=s."mediaType");
 DELETE FROM "Exercise" WHERE id=source_id AND "ownerUserId" IS NULL;
 UPDATE "Exercise" SET "updatedAt"=CURRENT_TIMESTAMP WHERE id=target_id;
 END IF; END LOOP;
END $$;
UPDATE "Exercise" SET name='Peck Deck',"updatedAt"=CURRENT_TIMESTAMP WHERE id='b9859cd9-6ed6-4e63-8fd0-500e8cf8d553' AND "ownerUserId" IS NULL;
UPDATE "Exercise" SET name='Crossover na Polia Média',"updatedAt"=CURRENT_TIMESTAMP WHERE id='46e31e5f-585b-4a3b-8b06-f6bed13440b5' AND "ownerUserId" IS NULL;
UPDATE "Exercise" SET name='Crossover na Polia Alta',"updatedAt"=CURRENT_TIMESTAMP WHERE id='daf02b04-9308-4b8f-8047-d4a5bb86d079' AND "ownerUserId" IS NULL;
UPDATE "Exercise" SET name='Crossover na Polia Baixa',"updatedAt"=CURRENT_TIMESTAMP WHERE id='dd8854e2-5652-4ffb-86bc-dbf61b42bd04' AND "ownerUserId" IS NULL;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='6ca42bbc-3724-45ec-98ed-36fb53af260a' AND ("ownerUserId" IS NOT NULL OR name <> 'Crucifixo na Máquina')) THEN RAISE EXCEPTION 'Machine fly identity collision'; END IF; END $$;
