UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Crucifixo sentado na máquina com pegadores, encosto e cotovelos levemente flexionados; sem apoios de antebraço.","aliases":["crucifixo máquina","machine fly","voador com pegadores"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020"]}],"sources":[{"id":"SAETERBAKKEN_2020","title":"Saeterbakken et al. — muscle activation in barbell bench press and dumbbell flyes (2020)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7675616/","limitation":"Dezessete homens treinados em 6RM; EMG não determina hipertrofia nem esforço individual."},{"id":"WELSCH_2005","title":"Welsch et al. — electromyographic activity during three upper-body lifts (2005)","url":"https://pubmed.ncbi.nlm.nih.gov/15903389/","limitation":"Doze participantes, EMG apenas do peitoral maior e deltoide anterior; não estabelece ênfase regional."},{"id":"ACE_CHEST_FLY","title":"ACE — Lying Chest Fly","url":"https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/","limitation":"Referência técnica de pegada neutra e punhos alinhados; não é ensaio de EMG nem demonstra superioridade de uma pegada."},{"id":"MACHINE_FLY_EQUIPMENT","title":"Life Fitness — Insignia Series Pectoral Fly/Rear Deltoid","url":"https://www.lifefitness.com/en-us/catalog/strength-training/selectorized/insignia-series-pectoral-fly-rear-deltoid","limitation":"Referência do equipamento e pegadores; extrapolação anatômica do gesto de adução horizontal, sem equivalência quantitativa entre EMG com halteres e máquina."}],"notes":"Peitoral maior primário; deltoide anterior e bíceps como participantes secundários. A participação do bíceps estabilizando a flexão do cotovelo é inferência anatômica. Não usar este cadastro para Peck Deck com apoio de antebraços. Não se estabelece ênfase regional.","instructions":{"description":"Adução horizontal na máquina com pegadores, sem apoio de antebraços.","setup":"Sente com costas no encosto e pés apoiados. Segure os pegadores à altura do peito, com cotovelos levemente flexionados.","execution":"Aproxime os pegadores em arco à frente do peito mantendo a flexão dos cotovelos. Reabra de forma controlada até uma amplitude confortável.","tips":"Mantenha o tronco apoiado. Esta variação usa pegadores; o Peck Deck usa apoios de antebraço. Participação muscular ilustrativa."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='6ca42bbc-3724-45ec-98ed-36fb53af260a' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Peck deck sentado, com encosto e apoios acolchoados nos antebraços; cotovelos flexionados e adução horizontal dos braços.","aliases":["peck deck","pec deck","voador com apoio de antebraços"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["ACE_PEC_DECK","MARCHETTI_PEC_DECK"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal","parte da frente do ombro"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["MARCHETTI_PEC_DECK"]}],"sources":[{"id":"ACE_PEC_DECK","title":"ACE-sponsored chest exercise research and pec deck technique (2012)","url":"https://www.acefitness.org/certifiednews/images/article/pdfs/ACE_BestChestExercises.pdf","limitation":"Relatório de estudo com 14 homens e orientações para a versão com apoios. Não estabelece ênfase regional, percentuais ilustrados nem equivalência de hipertrofia."},{"id":"MARCHETTI_PEC_DECK","title":"Marchetti et al. — rotação do ombro e atividade de peitoral maior/deltoide anterior no pec deck (2019)","url":"https://revistas.icesp.br/index.php/RBPeCS/article/view/733/","limitation":"Estudo isométrico com 10 homens treinados; apoia a participação dos músculos avaliados. Aplicação ao movimento dinâmico e subdivisões anatômicas é inferência, não uma medição direta de todas as regiões."}],"notes":"Peitoral maior como alvo e deltoide anterior como sinergista. Regiões nomeadas pela anatomia do músculo, sem alegar predominância superior/inferior, isolamento ou percentuais de ativação. A lista é ilustrativa e não inclui todo músculo estabilizador. Abertura limitada à linha dos ombros e parâmetros ajustados ao boneco; amplitude e regulagens variam com pessoa e equipamento.","instructions":{"description":"Adução horizontal dos braços na máquina peck deck, com peitoral maior como alvo e deltoide anterior como participante secundário.","setup":"Sente-se com as costas no encosto e pés firmes no chão. Ajuste o assento para apoiar cotovelos e antebraços junto à altura dos ombros, com os cotovelos flexionados.","execution":"Aproxime os apoios à frente do tórax, mantendo a flexão dos cotovelos. Retorne de forma controlada até a abertura confortável, sem levar os braços excessivamente para trás.","tips":"Mantenha o tronco apoiado, ombros sem encolher e a carga sob controle. A amplitude ilustrada depende do ajuste da máquina e não é uma prescrição individual."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='b9859cd9-6ed6-4e63-8fd0-500e8cf8d553' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Supino na máquina sentado com encosto vertical, pegadores na altura do peitoral médio e pés no chão; empurre horizontal anterior com extensão controlada dos cotovelos.","aliases":["supino na máquina","supino maquina","machine chest press","seated chest press","supino sentado na máquina","supino articulado","chest press"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]},{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior","peitoral clavicular"]}],"emphasizedRegionIds":[],"sourceIds":["CHEST_PRESS_2023"]},{"id":"TRICEPS_BRACHII","label":"Tríceps braquial","muscleGroup":"TRICEPS","role":"SECONDARY","aliases":["tríceps","triceps braquial","tríceps do braço"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CHEST_PRESS_2023"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["deltoide frontal","ombro anterior","parte frontal do ombro"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CHEST_PRESS_2023"]}],"sources":[{"id":"CHEST_PRESS_2023","title":"Comparison of Muscle Activity between the Horizontal Bench Press and the Seated Chest Press Exercises Using Several Grips (2023)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10203828/","limitation":"Comparação aguda de EMG em homens treinados, dependente da máquina e pegada. Não determina ângulo ideal universal, hipertrofia ou risco de lesão."}],"notes":"Empurrar horizontal sentado com costas apoiadas. Peitoral maior primário; tríceps e deltoide anterior secundários. Encosto, amplitude, cadência e angulações da ilustração são decisões editoriais, não ótimo universal nem medida de EMG.","instructions":{"description":"Empurrar horizontal na máquina de supino sentado com encosto vertical, tendo o peitoral maior como alvo principal e tríceps braquial e deltoide anterior como sinergistas.","setup":"Ajuste o assento para que as manoplas fiquem alinhadas à altura média do peitoral (linha dos mamilos / meio do esterno). Apoie as costas firmemente no encosto, mantenha os pés apoiados no chão e as escápulas estabilizadas.","execution":"Segure as manoplas com pegada firme e punhos neutros. Empurre à frente de maneira controlada até quase a extensão total dos braços, sem travar bruscamente os cotovelos. Retorne controlando a descida até sentir o alongamento confortável do peitoral.","tips":"Mantenha as costas apoiadas, punhos alinhados e cotovelos abaixo da linha dos ombros. Ajuste a amplitude ao equipamento e ao conforto individual; evite recuar os pegadores atrás do corpo."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='f3e5e1cf-d232-4a80-87b3-9f35650a1b5e' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Crucifixo bilateral com halteres em banco horizontal, cotovelos levemente flexionados e adução horizontal dos ombros.","aliases":["crucifixo reto com halteres"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020","WELSCH_2005"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["SAETERBAKKEN_2020"]}],"sources":[{"id":"SAETERBAKKEN_2020","title":"Saeterbakken et al. — muscle activation in barbell bench press and dumbbell flyes (2020)","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7675616/","limitation":"Dezessete homens treinados em 6RM; EMG não determina hipertrofia nem esforço individual."},{"id":"WELSCH_2005","title":"Welsch et al. — electromyographic activity during three upper-body lifts (2005)","url":"https://pubmed.ncbi.nlm.nih.gov/15903389/","limitation":"Doze participantes, EMG apenas do peitoral maior e deltoide anterior; não estabelece ênfase regional."},{"id":"ACE_CHEST_FLY","title":"ACE — Lying Chest Fly","url":"https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/","limitation":"Referência técnica de pegada neutra e punhos alinhados; não é ensaio de EMG nem demonstra superioridade de uma pegada."}],"notes":"Peitoral maior como alvo; deltoide anterior e bíceps braquial como participantes secundários. A participação como estabilizador do cotovelo é inferência anatômica. Sem ênfase regional estabelecida. A lista e a amplitude são ilustrativas, não medidas de EMG nem prescrição individual.","instructions":{"description":"Adução horizontal dos braços com halteres, com foco no peitoral maior.","setup":"Deite no banco reto com pés apoiados e halteres acima do peito, palmas voltadas uma para a outra.","execution":"Abra os braços em arco com cotovelos levemente flexionados, acompanhando o arco com as palmas voltadas para cima na abertura. Retorne com as palmas uma para a outra acima do peito, sem dobrar os punhos.","tips":"Mantenha o tronco apoiado e use uma amplitude confortável. A pose é ilustrativa."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='d555deb1-6eef-436d-8377-9427ac267697' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Crossover bilateral em pé na polia média, com cotovelos levemente flexionados.","aliases":["cross over na Polia Média","crucifixo no cabo na altura do peito"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]}],"sources":[{"id":"CABLE_EMG_2012","title":"Schanke — Electromyographical analysis of the pectoralis major muscle during various chest exercises (2012)","url":"https://core.ac.uk/download/pdf/10596984.pdf","limitation":"Comparação aguda incluindo crossover inclinado à frente e pec deck. Não comparou diretamente as três alturas de polia; as trajetórias são distinções mecânicas editoriais, sem ranking de ativação ou hipertrofia."}],"notes":"Peitoral maior primário e deltoide anterior secundário. Trajetória definida pela altura da polia; participação dos estabilizadores do tronco, escápula e cotovelo é inferência anatômica. Sem ênfase regional quantitativa ou isolamento. Cores são ilustrativas.","instructions":{"description":"Adução dos braços no crossover na polia média, com peitoral maior como alvo.","setup":"Ajuste as duas polias à altura do peito. Segure os pegadores e avance com base estável e cotovelos levemente flexionados.","execution":"Aproxime os pegadores horizontalmente à frente do peito. Reabra controlando pelo mesmo arco.","tips":"Preserve a leve flexão dos cotovelos e a estabilidade do tronco. A altura da polia muda a linha de resistência; não isola uma porção do peitoral."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='46e31e5f-585b-4a3b-8b06-f6bed13440b5' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Crossover bilateral em pé na polia alta, com cotovelos levemente flexionados.","aliases":["cross over na Polia Alta","crossover no cabo alto"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]}],"sources":[{"id":"CABLE_EMG_2012","title":"Schanke — Electromyographical analysis of the pectoralis major muscle during various chest exercises (2012)","url":"https://core.ac.uk/download/pdf/10596984.pdf","limitation":"Comparação aguda incluindo crossover inclinado à frente e pec deck. Não comparou diretamente as três alturas de polia; as trajetórias são distinções mecânicas editoriais, sem ranking de ativação ou hipertrofia."}],"notes":"Peitoral maior primário e deltoide anterior secundário. Trajetória definida pela altura da polia; participação dos estabilizadores do tronco, escápula e cotovelo é inferência anatômica. Sem ênfase regional quantitativa ou isolamento. Cores são ilustrativas.","instructions":{"description":"Adução dos braços no crossover na polia alta, com peitoral maior como alvo.","setup":"Ajuste as duas polias acima dos ombros. Segure os pegadores e avance com base estável e cotovelos levemente flexionados.","execution":"Aproxime os pegadores para baixo e para dentro, à frente da parte inferior do tórax. Retorne controlando pelo mesmo arco.","tips":"Preserve a leve flexão dos cotovelos e a estabilidade do tronco. A altura da polia muda a linha de resistência; não isola uma porção do peitoral."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='daf02b04-9308-4b8f-8047-d4a5bb86d079' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.2","reviewedAt":"2026-10-28T17:30:00.000Z","variant":"Crossover bilateral em pé na polia baixa, com cotovelos levemente flexionados.","aliases":["cross over na Polia Baixa","crucifixo no cabo baixo"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["CABLE_EMG_2012"]}],"sources":[{"id":"CABLE_EMG_2012","title":"Schanke — Electromyographical analysis of the pectoralis major muscle during various chest exercises (2012)","url":"https://core.ac.uk/download/pdf/10596984.pdf","limitation":"Comparação aguda incluindo crossover inclinado à frente e pec deck. Não comparou diretamente as três alturas de polia; as trajetórias são distinções mecânicas editoriais, sem ranking de ativação ou hipertrofia."}],"notes":"Peitoral maior primário e deltoide anterior secundário. Trajetória definida pela altura da polia; participação dos estabilizadores do tronco, escápula e cotovelo é inferência anatômica. Sem ênfase regional quantitativa ou isolamento. Cores são ilustrativas.","instructions":{"description":"Adução dos braços no crossover na polia baixa, com peitoral maior como alvo.","setup":"Ajuste as duas polias próximas ao chão. Segure os pegadores e avance com base estável e cotovelos levemente flexionados.","execution":"Aproxime os pegadores para cima e para dentro, à frente do peito. Retorne controlando pelo mesmo arco.","tips":"Preserve a leve flexão dos cotovelos e a estabilidade do tronco. A altura da polia muda a linha de resistência; não isola uma porção do peitoral."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP WHERE id='dd8854e2-5652-4ffb-86bc-dbf61b42bd04' AND "ownerUserId" IS NULL AND ("anatomyReview" IS NULL OR "anatomyReview"->>'version'='2026-10-28.1');
